const base = "C:\\Users\\jjq21\\.dsh\\our-free-model";
const r = await tools.pwsh({ command: `Get-ChildItem '${base}' -Force -Recurse -Depth 1 | Select-Object -First 60 FullName,Length | Format-Table -AutoSize`, description: "List our-free-model plugin files" });
console.log(r.kind === "foreground" ? r.stdout.text + r.stderr.text : JSON.stringify(r));

const pkg = await tools.pwsh({ command: `if (Test-Path '${base}\\package.json') { Get-Content '${base}\\package.json' -Raw }`, description: "Read plugin package.json" });
console.log("PKG:", pkg.kind === "foreground" ? pkg.stdout.text.slice(0, 3000) : "");
